import{_ as d,o as i,b as e,q as a}from"./chunks/framework.Tf23FRXt.js";const s="/assets/mini_game1.-vsmPj7h.jpg",l="/assets/mini_game2.BPlXKD_h.jpg",r="/assets/mini_game4.CvV3_kVZ.jpg",n="/assets/mini_game3.s9arRswA.jpg",p="/assets/mini_game6.C8yx0j-_.jpg",m="/assets/mini_game5.BbytTPp0.jpg",v=JSON.parse('{"title":"小游戏","description":"","frontmatter":{},"headers":[{"level":2,"title":"重击加美什","slug":"重击加美什","link":"#重击加美什","children":[]},{"level":2,"title":"莫古抓球机","slug":"莫古抓球机","link":"#莫古抓球机","children":[]},{"level":2,"title":"怪物投篮","slug":"怪物投篮","link":"#怪物投篮","children":[]},{"level":2,"title":"强袭水晶塔","slug":"强袭水晶塔","link":"#强袭水晶塔","children":[]},{"level":2,"title":"矿脉探索","slug":"矿脉探索","link":"#矿脉探索","children":[]},{"level":2,"title":"孤树无缘","slug":"孤树无缘","link":"#孤树无缘","children":[]}],"relativePath":"topic/gs-minigame.htm.md","filePath":"topic/gs-minigame.md","lastUpdated":1791101830000}'),h={name:"topic/gs-minigame.htm.md"};function o(_,t,g,c,b,k){return i(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="小游戏" tabindex="-1">小游戏</h1><p>金碟游乐场的小游戏散布在奇妙广场、演出广场和二楼走廊（地图上黑色带红色缎带的地方就是），基本上都是眼神杀类型的游戏，看好时机一锤定音。所有小游戏都需要 1 金碟币的费用（很像街机了）。另外玩家可以在综合柜台用金碟币购买<mark>强袭水晶塔</mark>、<mark>怪物投篮</mark>和<mark>重击加美什</mark>的家具，带回家摆在家里，就可以在家玩这些小游戏了！</p><h2 id="重击加美什" tabindex="-1">重击加美什</h2><p><img src="'+s+'" alt="" loading="lazy"><br> 在演出广场西北角。在蓄力条接近中央的地方，按下右侧的红色按钮即可出拳，越接近中央获得的金碟币越多 (最多 25 金碟币)。</p><p>如果迟迟不挥拳的话，蓄力条的移动速度会越来越慢。</p><h2 id="莫古抓球机" tabindex="-1">莫古抓球机</h2><p><img src="'+l+'" alt="" loading="lazy"><br> 演出广场东北角。跟娃娃机一样操作，先按住向右移动莫古力爪子，松开后再按它右边的按钮向上移动。大球 10 金碟币，小球 25 金碟币。只要蘑菇肚子碰到球基本就算成功 (不会有娃娃机调爪子力度这种事拉！)</p><h2 id="怪物投篮" tabindex="-1">怪物投篮</h2><p><img src="'+r+'" alt="" loading="lazy"><br> 奇妙广场北侧。类似投篮机，在进度条走到高亮 (蓝色) 区域按下按钮即可投中 (得 1 分)，30s 内投中 5 球以上就可以获得 50 金碟币。</p><h2 id="强袭水晶塔" tabindex="-1">强袭水晶塔</h2><p><img src="'+n+'" alt="" loading="lazy"><br> 奇妙广场南侧。进度条走到最右侧的时候按下按钮 (跟加美什那台非常接近了)，进度条越靠右，获得的金碟币越多。</p><p>如果迟迟不砸的话，蓄力条的移动速度会越来越慢。</p><h2 id="矿脉探索" tabindex="-1">矿脉探索</h2><p><img src="'+p+'" alt="" loading="lazy"><br> 二楼北侧 (可以小水晶传送宠物广场，或综合广场西侧坐电梯上二楼)。据说是 1.0 真实矿工采集系统的重现。首先需要选择难度，然后会出现一个像是雷达一样的盘，和一个不断缩放的红圈，如果玩家按下按钮时，红圈的大小与 “正确尺寸” 接近，那么雷达下方的进度条就会减少一部分。雷达上会留下上次按钮时红圈尺寸的记录，当进度条为 0 时，就算挑战成功。</p><p>可以多次挑战 (奖励也会增长)，但如果挑战失败，将无法获得之前积累的奖励。</p><p>因为难度很高，所以目前还没有人知道这个最多能获得多少金碟币 (有记载的是中级成功 3 次给 360)</p><h2 id="孤树无缘" tabindex="-1">孤树无缘</h2><p><img src="'+m+'" alt="" loading="lazy"><br> 二楼北侧 (可以小水晶传送宠物广场，或综合广场西侧坐电梯上二楼)。据说是 1.0 真实园艺采集系统的重现。首先需要选择难度，然后会出现一个扇形的木盘，和一个不断上下移动的游标，如果玩家按下按钮时，游标的位置与 “正确位置” 接近，那么木盘下方的进度条就会减少一部分。木盘上会留下上次按钮时游标位置的记录，当进度条为 0 时，就算挑战成功。</p><p>总计 1 分钟时间里，可以多次挑战 (奖励也会增长)，但如果挑战失败，将无法获得之前积累的奖励。</p><div class="md-table"><table class="ui compact grey striped unstackable table"><thead><tr><th>等级</th><th>1 次</th><th>2 次</th><th>3 次</th><th>4 次</th><th>5 次</th><th>6 次</th></tr></thead><tbody><tr><td>初级</td><td>50</td><td>100</td><td>150</td><td>400</td><td>500</td><td>600</td></tr><tr><td>中级</td><td>60</td><td>125</td><td>185</td><td>500</td><td>625</td><td>750</td></tr><tr><td>高级</td><td>85</td><td>175</td><td>260</td><td>700</td><td>875</td><td>1050</td></tr></tbody></table></div>',20)])])}const x=d(h,[["render",o]]);export{v as __pageData,x as default};
